def fact(identity,value,cf,roi,allowed=True):return dict(identity=identity,value=value,counterfactual=cf,roi=roi,cf_allowed=allowed)
def event(source,quote,readout,truth=None,**kw):
 return dict(source=source,quote=quote,readout=readout,truth=truth or readout,correctness=kw.pop('correctness','INCORRECT' if truth and truth!=readout else 'CORRECT'),**kw)
def record(base,template,facts,events,notes='',**kw):return dict(base=str(base),template=template,evidence_type=kw.pop('evidence_type','angle_label'),facts=facts,events=events,notes=notes,**kw)
